window.ScripturaLexicons.BDAG_PART_0184 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0184-01\" data-source=\"BDAG\" data-search=\"κακοποιέω verbo praticar o mal; prejudicar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κακοποιέω</td><td>verbo</td><td>praticar o mal; prejudicar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0184-02\" data-source=\"BDAG\" data-search=\"κακοποιός, όν adjetivo; substantivado malfeitor; criminoso BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κακοποιός, όν</td><td>adjetivo; substantivado</td><td>malfeitor; criminoso</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0184-03\" data-source=\"BDAG\" data-search=\"κακός, ή, όν adjetivo mau; perverso; prejudicial BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κακός, ή, όν</td><td>adjetivo</td><td>mau; perverso; prejudicial</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0184-04\" data-source=\"BDAG\" data-search=\"κακοτεχνία, ας, ἡ substantivo feminino astúcia; engano; intriga BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κακοτεχνία, ας, ἡ</td><td>substantivo feminino</td><td>astúcia; engano; intriga</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0184-05\" data-source=\"BDAG\" data-search=\"κακουργέω verbo maltratar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κακουργέω</td><td>verbo</td><td>maltratar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0184-06\" data-source=\"BDAG\" data-search=\"κακοῦργος, ον adjetivo; substantivado criminoso; malfeitor BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κακοῦργος, ον</td><td>adjetivo; substantivado</td><td>criminoso; malfeitor</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0184-07\" data-source=\"BDAG\" data-search=\"κακουχέω verbo maltratar; atormentar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κακουχέω</td><td>verbo</td><td>maltratar; atormentar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0184-08\" data-source=\"BDAG\" data-search=\"κακόω verbo prejudicar; maltratar; irritar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κακόω</td><td>verbo</td><td>prejudicar; maltratar; irritar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0184-09\" data-source=\"BDAG\" data-search=\"κακῶς advérbio mal; perversamente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κακῶς</td><td>advérbio</td><td>mal; perversamente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0184-10\" data-source=\"BDAG\" data-search=\"κάκωσις, εως, ἡ substantivo feminino opressão; maus-tratos BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κάκωσις, εως, ἡ</td><td>substantivo feminino</td><td>opressão; maus-tratos</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0184-11\" data-source=\"BDAG\" data-search=\"καλάμη, ης, ἡ substantivo feminino palha; haste vegetal BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καλάμη, ης, ἡ</td><td>substantivo feminino</td><td>palha; haste vegetal</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0184-12\" data-source=\"BDAG\" data-search=\"κάλαμος, ου, ὁ substantivo masculino cana; vara; cálamo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κάλαμος, ου, ὁ</td><td>substantivo masculino</td><td>cana; vara; cálamo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0184-13\" data-source=\"BDAG\" data-search=\"καλάνδαι, ῶν, αἱ substantivo feminino plural calendas romanas BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καλάνδαι, ῶν, αἱ</td><td>substantivo feminino plural</td><td>calendas romanas</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0184-14\" data-source=\"BDAG\" data-search=\"καλέω verbo chamar; nomear; convidar; convocar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καλέω</td><td>verbo</td><td>chamar; nomear; convidar; convocar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0184-15\" data-source=\"BDAG\" data-search=\"καλιά, ᾶς, ἡ substantivo feminino ninho BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καλιά, ᾶς, ἡ</td><td>substantivo feminino</td><td>ninho</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0184-16\" data-source=\"BDAG\" data-search=\"καλλιέλαιος, ου, ἡ substantivo feminino oliveira cultivada BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καλλιέλαιος, ου, ἡ</td><td>substantivo feminino</td><td>oliveira cultivada</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0184-17\" data-source=\"BDAG\" data-search=\"κάλλιον remissão lexical ver καλῶς 7 BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κάλλιον</td><td>remissão lexical</td><td>ver καλῶς 7</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0184-18\" data-source=\"BDAG\" data-search=\"καλλονή, ῆς, ἡ substantivo feminino beleza BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καλλονή, ῆς, ἡ</td><td>substantivo feminino</td><td>beleza</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0184-19\" data-source=\"BDAG\" data-search=\"κάλλος, ους, τό substantivo neutro beleza BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κάλλος, ους, τό</td><td>substantivo neutro</td><td>beleza</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0184-20\" data-source=\"BDAG\" data-search=\"καλλωπίζω verbo adornar; embelezar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καλλωπίζω</td><td>verbo</td><td>adornar; embelezar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0184-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κακοποιέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">1º aoristo <span class=\"greek\">ἐκακοποίησα</span> (veja o artigo seguinte; Aeschyl. e outros; inscrições, papiros, LXX; Test12Patr; Ar. 13, 5; Tat. 17, 4).\n ① praticar o que é mau ou injusto; agir mal; ser malfeitor ou criminoso, uso intransitivo (X., Oec. 3, 11; PHib 59, 10 [III b.c.]; Pr 4:16; TestAsh 2:8) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.3.17\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 3:17</a>; 3J 11. Também <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 3:4</a>=<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.9\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:9</a> poderia pertencer a essa acepção. Entretanto, nessas passagens a palavra pode significar\n ② prejudicar, lesar (X., Mem. 3, 5, 26 al.; Musonius 32, 17; SIG 736, 103; 1243, 15; EpArist 164; 168; Gen 31:7; Num 35:23; TestJos 18:2; PFouad 203, 14 <span class=\"greek\">ψυχήν</span>). Nas quatro passagens do Novo Testamento, contrapõe-se a <span class=\"greek\">ἀγαθοποιέω</span>.—M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0184-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κακοποιός, όν</h1><div class=\"entry-meta\"><span>adjetivo; substantivado</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(veja o artigo precedente; Pind. e outros; Hippol.) relativo à prática do mal (Aristot., EN 4, 9 p. 1125a, 18f; Polyb. 15, 25, 1; Sallust. 9 p. 18, 19; Pr 12:4; AscIs 3:13; Ar. 13, 6 [feminino]) substantivado: malfeitor, criminoso (escólio sobre Nicander, Alex. 569; PMich 149 [II a.d.], 10; 16 e outros; Pr 24:19) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.18.30\" target=\"_blank\" rel=\"noopener noreferrer\">J 18:30</a> v.l.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 2:12</a>; 3:16 v.l.; 4:15 (quanto aos argumentos favoráveis à acepção «feiticeiro», veja o comentário de ESelwyn ao trecho). Em oposição a <span class=\"greek\">ἀγαθοποιός</span> 2:14 (Artem. 4, 59 p. 238, 9; 11).—M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0184-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κακός, ή, όν</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(documentado desde Homero; em sentido geral, refere-se ao que não corresponde aos padrões aceitos de comportamento: «mau», «sem valor», «inferior»).\n ① relativo ao que é social ou moralmente reprovável: mau, perverso (Hom.+; LXX)\n ⓐ referente a pessoas: <span class=\"greek\">ὁ κ</span>. <span class=\"greek\">δοῦλος</span> o escravo mau <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.48\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:48</a> (TestJob 7:7 <span class=\"greek\">κακὴ δούλη</span>); <span class=\"greek\">κ</span>. <span class=\"greek\">ἐργάτης</span> malfeitor <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.3.2\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 3:2</a>. Substantivado, sem artigo, (Sir 20:18) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.2\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 2:2</a>. <span class=\"greek\">κακοὺς κακῶς ἀπολέσει</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.41\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:41</a> (cf. Hipponax [VI b.c.] 77, 3 D.3; Soph., Phil. 1369; Aristipo em Diog. L. 2, 76 <span class=\"greek\">κακοὶ κακῶς ἀπόλοιντο</span>; Nicol. Dam.: 90 Fgm. 66, 33 Jac.; Cebes 32, 5; Alciphron 2, 2, 1 <span class=\"greek\">κακὸς κακῶς ἀπόλοιτο</span>; Jos., Ant. 2, 300; 7, 291; 12, 256; SIG 526, 46f [III b.c.] <span class=\"greek\">ἐξόλλυσθαι κακῶς κακούς</span>; POxy 1238, 5 <span class=\"greek\">κακὸς κακῶς ἀπόλ</span>.).—New Docs 4 p. 31 [lit.].\n ⓑ referente a características humanas, ações, emoções, planos etc. (POxy 532, 22 [II a.d.] <span class=\"greek\">ὑπὸ κακοῦ συνειδότος κατεχόμενος</span>; 2 Macc 5:8; 4 Macc 17:2; Just., D. 17, 1 <span class=\"greek\">κακῆς προλήψεως</span>; 94, 2 <span class=\"greek\">κ</span>. <span class=\"greek\">πράξεις</span>; 121, 3 <span class=\"greek\">πολιτείας</span>) <span class=\"greek\">διαλογισμοί</span> maus pensamentos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.7.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 7:21</a>. <span class=\"greek\">ἐπιθυμία</span> desejo vil (Menand., Fgm. 718, 7 Kö.=535, 7 Kock; Pr 12:12; Just., A I, 10, 6) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.3.5\" target=\"_blank\" rel=\"noopener noreferrer\">Col 3:5</a>; <span class=\"greek\">ἔργον κ</span>. má ação <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.13.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 13:3</a>. <span class=\"greek\">ὁμιλίαι</span> más companhias, más relações <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.33\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 15:33</a> (veja <span class=\"greek\">ἦθος</span>). <span class=\"greek\">διδασκαλία</span> IEph 16:2; cf. 9:1.\n ⓒ neutro substantivado (Hom.+; ins, pap, LXX, TestAsh 1:5; 4:5; Philo; Just., D. 1, 5 al.) <span class=\"greek\">τὸ κακόν</span> mal, injustiça: aquilo que contraria os costumes ou a lei <span class=\"greek\">εἰ κακῶς ἐλάλησα</span>, <span class=\"greek\">μαρτύρησον περὶ τοῦ κακοῦ</span> se falei de maneira errada, dá testemunho do que houve de errado nisso <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.18.23\" target=\"_blank\" rel=\"noopener noreferrer\">J 18:23</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.7.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 7:21</a> (em oposição a <span class=\"greek\">τὸ καλόν</span>, o correto, o belo, a ação admirável) (Maximus Tyr. 34, 2a: a alma sucumbe ao <span class=\"greek\">κακόν</span>, contra seus próprios esforços e apesar de suas lutas); 16:19; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.13.5\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 13:5</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.5.14\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 5:14</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.3.10\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 3:10f</a>; 1 Cl 22, 4 (both Ps 33:15); 3J 11. Talvez também <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.14.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 14:20</a> (veja a acepção 2 abaixo). <span class=\"greek\">οὐδὲν κ</span>. nada de errado <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.23.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 23:9</a>. No plural: ações más (Ael. Aristid. 45 p. 74 D.; TestSim 5:3; Ar. 13, 7; Just., A I, 28, 4) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.30\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 1:30</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.10.6\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 10:6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.1.13\" target=\"_blank\" rel=\"noopener noreferrer\">Js 1:13</a> (veja <span class=\"greek\">ἀπείραστος</span>); <span class=\"greek\">πάντα τὰ κ</span>. todos os males <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.6.10\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 6:10</a>. <span class=\"greek\">μῆνις</span> … <span class=\"greek\">ἐκ τοσούτων κακῶν συνισταμένη</span> vingança constituída de tantos males Hm 5, 2, 4.—<span class=\"greek\">κακὸν ποιεῖν</span> praticar o mal (Menand., Sam. 652 S. [307 Kö.]; Eccl 4:17; Plut., Mor. 523a) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:23</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.14\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 15:14</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.22\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 23:22</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.18.30\" target=\"_blank\" rel=\"noopener noreferrer\">J 18:30</a> (veja <span class=\"greek\">κακαποιός</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.13.7\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 13:7</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.3.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 3:12</a> (Ps 33:17). Também <span class=\"greek\">τὸ κ</span>. <span class=\"greek\">ποιεῖν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.13.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 13:4a</a>; <span class=\"greek\">τὰ κ</span>. <span class=\"greek\">ποιεῖν</span> (Pr 16:12) 3:8; cf. GPt 4:13. (<span class=\"greek\">τὸ</span>) <span class=\"greek\">κ</span>. <span class=\"greek\">πράσσειν</span> (TestAsh 6:2; apenas no plural Pr 10:23 e Just., D. 108, 1) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.7.19\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 7:19</a>; 9:11 v.l.; 13:4b; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.5.10\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 5:10</a> v.l. <span class=\"greek\">κατεργάζεσθαι τὸ κ</span>. 2:9.\n ② relativo ao que causa dano ou prejuízo: mau, nocivo, perigoso, pernicioso, quanto a coisas ou situações (Pr 16:9 <span class=\"greek\">ἡμέρα κ</span>.; TestAbr B 4 p. 108, 12 [Stone p. 64] <span class=\"greek\">οὐδὲν κ</span>.; Just., A I, 2, 3 <span class=\"greek\">φήμη κ</span>.) <span class=\"greek\">ἕλκος κ</span>. <span class=\"greek\">καὶ πονηρόν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.16.2\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 16:2</a>. <span class=\"greek\">κ</span>. <span class=\"greek\">θηρία</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.1.12\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 1:12</a> (cf. POxy 1060, 7 <span class=\"greek\">ἀπὸ παντὸς κακοῦ ἑρπετοῦ</span>. Quanto à aplicação a seres humanos, veja <span class=\"greek\">θηρίον</span> 2). <span class=\"greek\">θανάσιμον φάρμακον</span> …, <span class=\"greek\">ὅπερ ὁ ἀγνοῶν ἡδέως λαμβάνει ἐν ἡδονῇ κακῇ</span> um veneno mortal que o ignorante recebe com prazer perigoso ITr 6:2 (cf. Just., A I, 21, 5 <span class=\"greek\">κακῶν καὶ αἰσχρῶν ἡδονῶν</span>). Substantivado, <span class=\"greek\">τὸ κακόν</span>, «o mal» (Susario Com. [VI b.c.] <span class=\"greek\">κακὸν γυναῖκες</span>; AnthLG: Fgm. iamb. adespecialmente 29 Diehl <span class=\"greek\">δῆμος ἄστατον κακόν</span>; Ps.-Pla., Eryxias 8, 395e: opp. <span class=\"greek\">τὸ ἀγαθόν</span>; Apollon. Rhod. 3, 129; Theocr. 14, 36; Plut., Lysander 18, 9 sobre <span class=\"greek\">ἄγνοια</span>; Maximus Tyr. 24, 4a <span class=\"greek\">μέγιστον ἀνθρώπῳ κακὸν ἐπιθυμία</span> «o desejo de ter sempre mais é a pior desgraça da humanidade»; TestGad 3:1 [<span class=\"greek\">μῖσος</span>]; Philo, Rer. Div. Her. 287 [<span class=\"greek\">λιμὸς</span>] … <span class=\"greek\">κακὸν χεῖρον</span>) com referência à língua <span class=\"greek\">ἀκατάστατον κακόν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.3.8\" target=\"_blank\" rel=\"noopener noreferrer\">Js 3:8</a> (veja <span class=\"greek\">ἀκατάστατος</span>). (<span class=\"greek\">τὰ</span>) <span class=\"greek\">κακά</span>, infortúnios (Appian, Iber. 79, §338; Maximus Tyr. 41, 3aff; schol. on Soph., Trach. 112 p. 286 Papag.; Is 46:7; EpArist 197; 207; TestJob 23:6; TestLevi 10:2; Jos., Bell. 6, 213, Ant. 3, 86) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.16.25\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 16:25</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.24\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 8:24</a> D; 2 Cl 10:1; AcPl Ha 3, 10; 11:7. <span class=\"greek\">κακόν τι πάσχειν</span> sofrer dano <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.28.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 28:5</a> (cf. EpJer 33; Jos., Ant. 12, 376; Just., A I, 2, 4; Ath. 12, 1). <span class=\"greek\">πράσσειν ἑαυτῷ κ</span>. causar dano a si mesmo 16:28. <span class=\"greek\">τί κ</span>. <span class=\"greek\">ἐστιν</span>; seguido de infinitivo: que mal há nisso? MPol 8:2. Provavelmente <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.14.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 14:20</a> (veja 1c acima), <span class=\"greek\">κ</span>. <span class=\"greek\">τῷ ἀνθρώπῳ</span>, «nocivo ao homem», pertence a esta acepção. <span class=\"greek\">ἡσυχάσει ἄφοβος ἀπὸ παντὸς κακοῦ</span> terá descanso sem temor de mal algum 1Cl 57:7 (Pr 1:33).\n ③ Certas passagens situam-se entre as acepções 1 e 2; nelas, o dano provém de intenção má, de modo que as acepções 1 e 2 se combinam: maldade, dano, injustiça <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.12.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 12:21a</a>b (cf. o provérbio sob o verbete <span class=\"greek\">ἰάομαι</span> 2b. Também Polyaenus 5, 11 <span class=\"greek\">οὐ κακῷ κακὸν ἠμυνάμην</span>, <span class=\"greek\">ἀλλ</span>’ <span class=\"greek\">ἀγαθῷ κακόν</span>; mas veja SRobertson, ET 60, ’48/49, 322). <span class=\"greek\">κακά τινι ποιεῖν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 9:13</a> (o dativo como em 4Km 8:12; TestJud 7:8 <span class=\"greek\">οὐδὲν κακόν</span>; Vi. Aesopi G 11 P.; Witkowski 64, 12 [95 b.c.]=PGrenf II, 36 <span class=\"greek\">ἡμῖν κακὸν ἐποίησεν</span>; veja B-D-F §157). (<span class=\"greek\">διάβολος</span>) <span class=\"greek\">ποιήσει τι κακὸν τοῖς δούλοις τοῦ θεοῦ</span> (o diabo) causará algum tipo de dano aos servos de Deus Hm 4, 3, 4. <span class=\"greek\">κακόν τινι ἐργάζεσθαι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.13.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 13:10</a>. <span class=\"greek\">κακά τινι ἐνδείκνυσθαι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.4.14\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 4:14</a> (cf. Da 3:44; TestZeb 3:8). (<span class=\"greek\">τινί</span>) <span class=\"greek\">κακὸν ἀντὶ κακοῦ ἀποδιδόναι</span> (cf. Paroem. Gr.: Apostol. 18, 33 <span class=\"greek\">χρὴ μὴ τὸ κακὸν διὰ κακοῦ ἀμύνασθαι</span>; Mel., P. 90, 676 <span class=\"greek\">ἀνταποδοὺς</span> … <span class=\"greek\">κακὰ ἀντὶ καλῶν</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.12.17\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 12:17</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.5.15\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 5:15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.3.9\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 3:9</a>; Pol 2:2.—WLofthouse, Poneron and Kakon in O and NT: ET 60, ’48/49, 264–68; veja <span class=\"greek\">κακία</span> (GBaumbach).—B. 1177. DELG. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0184-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κακοτεχνία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(veja <span class=\"greek\">κακός</span>, <span class=\"greek\">τέχνη</span>; Pla. e outros; inscrições e papiros) astúcia, engano; no plural, intrigas (Lucian, Calumn. 12, Alex. 4) referente ao diabo, junto de <span class=\"greek\">ἐνέδραι</span> IPhld 6:2.—Em IPol 5:1, onde não há referência ao diabo e Policarpo é aconselhado a fazer de <span class=\"greek\">κακοτεχνίαι</span> assunto de pregação, a palavra parece significar «artes maléficas», isto é, artes e ofícios proibidos ao cristão, especialmente a magia. Favorece essa interpretação o fato de que o contexto da passagem trata das relações conjugais de modo a sugerir uma advertência contra o recurso a fórmulas mágicas de temática erótica. Veja Zahn, Ign. von Ant. 1873, 321; Lghtf. e Hdb., comentários ao trecho. Quanto aos encantamentos destinados a amantes, veja HBetz, The Greek Magical Papyri in Translation including the Demotic Spells, I, ’86.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0184-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κακουργέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(veja o artigo seguinte; Eur., Thu. e outros; inscrições e papiros; TestSol 7:7; EpArist 271) maltratar (Jos., Bell. 2, 277, Ant. 2, 101 al.) na voz passiva, referindo-se à alma <span class=\"greek\">κακουργουμένη σιτίοις καὶ ποτοῖς ἡ ψυχή</span> a alma quando maltratada quanto à comida e à bebida, isto é, quando privada de alimento e bebida suficientes Dg 6:9.—M-M sob o verbete <span class=\"greek\">κακοῦργος</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0184-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κακοῦργος, ον</h1><div class=\"entry-meta\"><span>adjetivo; substantivado</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(veja o artigo precedente; [na forma <span class=\"greek\">κακοεργός</span> Od. 18, 54] Soph., Hdt.+; TestSol 4:6; SibOr 5:386419; ; Just., A I, 7, 1, D. 22, 5 [s. Am 6:7]) usualmente substantivado: <span class=\"greek\">ὁ κ</span>. criminoso, malfeitor (Thu. 1, 134, 4 al.; Menand., Dyscolus 258; OGI 669 17 [I a.d.]; PLille 7, 20 [III b.c.]; PFay 108, 11; LXX; Philo, In Flacc. 75; Jos., Ant. 2, 59), aquele que comete grandes delitos e crimes graves (Diod S 20, 81, 3 referindo-se a piratas; Ep. Socr. 30, 6 com <span class=\"greek\">παράνομος</span>; Syntipas p. 61, 7; 114, 1 com <span class=\"greek\">λῃστής</span>; em oposição ao <span class=\"greek\">εὐσεβής</span>: Lycurgus, Contra Leocratem 93) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.32\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 23:32f</a>, 39 (Plut., Mor. 554b); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.2.9\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 2:9</a>; GPt 4:10, 13; 7:26; Ox 840, 5.—DELG sob o verbete <span class=\"greek\">ἔργον</span> I 1 p. 364. M-M. TW. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0184-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κακουχέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(veja <span class=\"greek\">κακός</span>, <span class=\"greek\">ἔχω</span>; atestada desde Teles p. 34, 8; papiros [em contratos de casamento]) maltratar, atormentar; voz passiva (Diod S 3, 23, 3; 19, 111, 4; Cass. Dio 35, 9; Plut., Mor. 114e; 3 Km 2:26) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.37\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:37</a>; 13:3.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0184-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κακόω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">futuro <span class=\"greek\">κακώσω</span>; 1º aoristo <span class=\"greek\">ἐκάκωσα</span>; perfeito, 2ª pessoa do singular <span class=\"greek\">κεκάκωκας</span> 3 Km 17:20. Na voz passiva: 1º aoristo <span class=\"greek\">ἐκακώθην</span> LXX; infinitivo perfeito <span class=\"greek\">κεκακῶσθαι</span>.\n ① causar dano a, prejudicar, maltratar, com acusativo (Hom.+; PTebt 407, 9 [II a.d.]; LXX; TestSol 8:11; Test12Patr; Philo, Spec. Leg. 2, 135; Jos., Vi. 121; Just., D. 109, 3 [s. Mi 4:6]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:6</a> (Gen 15:13), 19; 12:1; 18:10; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.3.13\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 3:13</a>. Na voz passiva, 1 Cl 16:7 (Is 53:7).\n ② levar alguém a pensar mal de outrem, irritar, criar amargura <span class=\"greek\">τὰς ψυχάς τινων κατά τινος</span> envenenar o ânimo de algumas pessoas contra outra <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.14.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 14:2</a> (cf. Jos., Ant. 16, 10; pass., 16, 205; 262; Ps 105:32).—DELG sob o verbete <span class=\"greek\">κακό</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0184-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κακῶς</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">advérbio de <span class=\"greek\">κακός</span> (Hom.+) em sentido geral, «mal»\n ① relativo à experiência de dano físico, mal, de maneira ruim\n ⓐ sem indicação de intensidade na expressão <span class=\"greek\">κ</span>. <span class=\"greek\">ἔχειν</span> estar doente, enfermo (<span class=\"greek\">ἔχω</span> 10b) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.4.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 4:24</a>; 8:16; 9:12b; 14:35; 17:15 v.l.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:32</a>, 34; 2:17; 6:55; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.31\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:31</a>; 7:2.\n ⓑ com indicação de intensidade <span class=\"greek\">κ</span>. <span class=\"greek\">πάσχειν</span> (Aeschyl., Prom. 759; Polyb. 3, 90, 13) sofrer intensamente <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.17.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 17:15</a>. <span class=\"greek\">δαιμονίζεσθαι</span> ser gravemente atormentado por um demônio 15:22.—<span class=\"greek\">κακοὺς κ</span>. <span class=\"greek\">ἀπολέσει</span> (<span class=\"greek\">κακός</span> 1a) 21:41.\n ② relativo ao que é moralmente mau: indevidamente, perversamente (como em Just., A I, 4, 7 <span class=\"greek\">κ</span>. <span class=\"greek\">ζῆν</span> al.): <span class=\"greek\">κ</span>. <span class=\"greek\">διακονεῖν</span> Hs 9, 26, 2. <span class=\"greek\">κ</span>. <span class=\"greek\">λαλεῖν</span> falar de modo errado ou perverso (1 Macc 7:42) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.18.23\" target=\"_blank\" rel=\"noopener noreferrer\">J 18:23</a>. Também <span class=\"greek\">κ</span>. <span class=\"greek\">εἰπεῖν</span> (Libanius, Or. 51 p. 9, 11 F. [em oposição a <span class=\"greek\">ἐπαινεῖν</span>]; Jos., Ant. 6, 299) com acusativo: contra alguém ou a respeito de alguém (Pítaco em Diog. L. 1, 78 <span class=\"greek\">φίλον μὴ λέγειν κακῶς</span>; Diod S 27, 4, 4; Artem. 3, 48; Lucian, Pisc. 6; Procop. Soph., Ep. 161 p. 596) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.23.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 23:5</a> (Ex 22:27; Is 8:21). <span class=\"greek\">κ</span>. <span class=\"greek\">αἰτεῖσθαι</span> pedir com motivos errados <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.4.3\" target=\"_blank\" rel=\"noopener noreferrer\">Js 4:3</a>.—M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0184-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κάκωσις, εως, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(Thu. e outros; Vett. Val. índice; PSI 158, 16; LXX, ParJer, Philo; Jos., Bell. 1, 444, Ant. 13, 151; TestNapht 4:2; diferentemente em TestGad 8:2 <span class=\"greek\">πονηρίᾳ καὶ κακώσει</span> «vileza e perversidade») maus-tratos, opressão (Appian, Samn. 2 §2; Sextus 96) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.34\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:34</a> (Ex 3:7). Com <span class=\"greek\">πληγή</span> 1 Cl 16:4 (Is 53:4).—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0184-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καλάμη, ης, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(Hom. e outros; papiros, LXX) haste vegetal, palha como material de construção (cf. Diod S 5, 21, 5 <span class=\"greek\">οἰκήσεις ἐκ τῶν καλάμων ἢ ξύλων</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.3.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 3:12</a> (singular coletivo, como em Arrian, Ind. 27, 9); a acepção «restolho» (Hom. e outros, pap) é menos provável.—DELG sob o verbete <span class=\"greek\">κάλαμος</span> 2. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0184-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κάλαμος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(Pind., Hdt. e outros; papiros, LXX, TestSol 5:6 L; TestAbr; TestNaphth 2:8 [traqueia]; JosAs; ApcMos 29; Joseph.; empréstimo lexical na literatura rabínica).\n ① cana, junco (para descrição detalhada, veja Theophr., HP 4, 11 [também RStrömberg, Theophrastea ’37, 100f]; 3 Km 14:15; Job 40:21; JosAs), agitado pelo vento (Lucian, Hermot. 68 <span class=\"greek\">ἐοικὼς</span> … <span class=\"greek\">καλάμῳ</span> … <span class=\"greek\">πρὸς πᾶν τὸ πνέον καμπτομένῳ</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.11.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 11:7</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.24\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:24</a>; facilmente quebrável <span class=\"greek\">κ</span>. <span class=\"greek\">συντετριμμένος</span> uma cana rachada <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:20</a> (cf. Is 42:3 e veja PvanDijk, Het gekrookte riet en de rookende vlaswiek [<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:18</a> vv.ll.]: GereformTT 23, 1923, 155–72).\n ② haste, vara (Artem. 2, 48 p. 150; cp. 4 Km 18:21 <span class=\"greek\">ἡ ῥάβδος ἡ καλαμίνη</span>=Jos., Ant. 10, 7 <span class=\"greek\">κάλαμος</span>; TestSol 5:6 L) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.29\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:29f</a>, 48 (segundo Zohary, Plants 134, a espécie Phragmitis australis); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 15:19</a>, 36; GPt 3:9.\n ③ cana de medir (PRyl 64, 2; Ezk 40:3ff; 42:16ff) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.11.1\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 11:1</a>; 21:15f.\n ④ cálamo de escrever (Pla., Phdr. 61 p. 276c; Plut., Demosth. 29, 4; Lucian, Hist. Conscr. 38; Themist., In Constant. p. 31c <span class=\"greek\">ἐν καλάμῳ καὶ μέλανι</span>; PGrenf II, 38, 7 [81 b.c.]; POxy 326; 521, 21; Ps 44:2; 3 Macc 4:20; TestAbr A 12 p. 91, 4 [Stone p. 30]) 3J 13.—B. 1290. DELG. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0184-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καλάνδαι, ῶν, αἱ</h1><div class=\"entry-meta\"><span>substantivo feminino plural</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(empréstimo do latim: calendae.—Dionys. Hal. 6, 48; 8, 55; 9, 67; 16, 3; Plut., Numa 61 [3, 6], Mar. 412 [12, 3]; inscrições [índices em SIG e OGI]; papiros [Preis., III 90]; Jos., Ant. 14, 228; empréstimo na literatura rabínica) calendas, primeiro dia do mês no calendário romano <span class=\"greek\">πρὸ ἐννέα καλανδῶν Σεπτεμβρίων</span>=em 24 de agosto IRo 10:3. <span class=\"greek\">πρὸ ἑπτὰ καλ</span>. <span class=\"greek\">Μαρτίων</span> em 23 de fevereiro MPol 21.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0184-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καλέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">imperfeito <span class=\"greek\">ἐκάλουν</span>; futuro <span class=\"greek\">καλέσω</span> (LXX; JosAs 17:5; 20:6; Jos., Ant. 11, 266.—W-S. §13, 5; B-D-F §74, 1; Mlt-H. 242); 1º aoristo <span class=\"greek\">ἐκάλεσα</span>; perfeito <span class=\"greek\">κέκληκα</span>. Na voz média: futuro, 3ª pessoa do singular <span class=\"greek\">καλέσεται</span> (Just., D. 43, 5). Na voz passiva: 1º futuro <span class=\"greek\">κληθῆσομαι</span> (W-S. §15); 2º futuro, 3ª pessoa do singular <span class=\"greek\">κεκλήσεται</span> Lev 13:45; Hos 12:1; 1º aoristo <span class=\"greek\">ἐκλήθην</span>; perfeito <span class=\"greek\">κέκλημαι</span> (atestada desde Homero).\n ① identificar por nome ou atributo, chamar, chamar pelo nome, nomear\n ⓐ chamar (alguém), em uso absoluto, com referência implícita ao nome (em oposição a <span class=\"greek\">ὑπακούειν</span>; cf. PHamb 29, 3 [89 a.d.] <span class=\"greek\">κληθέντων τινῶν καὶ μὴ ὑπακουσάντων</span>; Just., D. 136, 2 <span class=\"greek\">οὔτε καλοῦντος αὐτοῦ ἀνέχεσθε οὔτε λαλοῦντος ἀκούετε</span>) referindo-se a Deus <span class=\"greek\">ἐκάλουν καὶ οὐχ ὑπηκούσατε</span> 1 Cl 57:4 (Pr 1:24); com objeto <span class=\"greek\">τὰ ἴδια πρόβατα καλεῖ κατ</span>’ <span class=\"greek\">ὄνομα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.10.3\" target=\"_blank\" rel=\"noopener noreferrer\">J 10:3</a> variante textual\n ⓑ chamar, dirigir-se a alguém como, designar como, com duplo acusativo (Just., D. 3, 5 <span class=\"greek\">θεὸν σὺ τί καλεῖς</span>; Hippol., Ref. 6, 20, 1) <span class=\"greek\">αὐτὸν καλῶμεν κύριον</span> 2 Cl 4:1; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.22.43\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 22:43</a>, 45; 23:9 (a acepção pressupõe o segundo acusativo: não deveis chamar ninguém de vosso pai); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.20.44\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 20:44</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.14.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 14:12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.9.25\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 9:25</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.2.11\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 2:11</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.17\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 1:17</a> P72; 3:6. O vocativo pode ocupar o lugar do segundo acusativo. <span class=\"greek\">τί με καλεῖτε κύριε</span>, <span class=\"greek\">κύριε</span>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.46\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:46</a>. Na voz passiva: <span class=\"greek\">καλεῖσθαι ὑπὸ τῶν ἀνθρώπων ῥαββί</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.23.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 23:7</a>. <span class=\"greek\">ὑμεῖς μὴ κληθῆτε ῥαββί</span> não deveis permitir que as pessoas vos chamem «rabi» versículo 8; versículo 10. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.25\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 22:25</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.2.23\" target=\"_blank\" rel=\"noopener noreferrer\">Js 2:23</a>. <span class=\"greek\">ὁ οἶκός μου οἶκος προσευχῆς κληθήσεται</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.11.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 11:17</a> (ambas as passagens citam Is 56:7). <span class=\"greek\">κληθήσονται υἱοὶ θεοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.9.26\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 9:26</a> (Hos 2:1).\n ⓒ dar nome, nomear, com duplo acusativo (Iren. 1, 1, 1 [Harv. I 8, 3]) <span class=\"greek\">ἐκάλουν αὐτὸ</span> … <span class=\"greek\">Ζαχαρίαν</span> pretendiam dar-lhe o nome de Zacarias <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.59\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:59</a> (sobre <span class=\"greek\">ἐπὶ τῷ ὀνόματι τ</span>. <span class=\"greek\">πατρός</span>, «segundo o nome de seu pai», cf. 1 Esdr 5:38; Sir 36:11 e veja Hs 9, 17, 4).—Na voz passiva: receber um nome, ser nomeado (Jos., Ant. 1, 34) <span class=\"greek\">κληθήσεται Ἰωάννης</span> seu nome será João <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.60\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:60</a>; cf. versículo 62. <span class=\"greek\">σὺ κληθήσῃ Κηφᾶς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.42\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:42</a>. Também a respeito de localidades <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.19\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 1:19</a>; ApcPt Rainer (veja <span class=\"greek\">Ἀχερουσία</span>).—Ter por nome, chamar-se (Lucian, Jud. Voc. 7 <span class=\"greek\">Λυσίμαχος ἐκαλεῖτο</span>; Just., D. 1, 3 <span class=\"greek\">Τρύφων</span>…<span class=\"greek\">καλοῦμαι</span>; 63, 5 <span class=\"greek\">Χριστιανοὶ</span> … <span class=\"greek\">καλούμεθα</span>) <span class=\"greek\">ὸ̔ς καλεῖται τ</span>. <span class=\"greek\">ὀνόματι τούτῳ</span> aquele que traz este nome <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.61\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:61</a>. Também a respeito de localidades (Appian, Bell. Civ. 3, 70 §289; 3, 91 §374; SIG 599, 5 <span class=\"greek\">τὸ φρούριον ὸ̔ καλεῖται Κάριον</span>; Just., A I, 59, 6 <span class=\"greek\">τὸ καλούμενον Ἔρεβος</span>) <span class=\"greek\">πόλις Δαυὶδ ἥτις καλεῖται Βηθλέεμ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.4\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:4</a>. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.28.1\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 28:1</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.11.8\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 11:8</a>.—Lucas, Atos, Apocalipse e o Evangelho de Pedro acrescentam a uma pessoa ou coisa o nome ou sobrenome que ela possui por meio do particípio presente passivo. (cf. SIG 685, 39 <span class=\"greek\">νῆσον τὴν καλουμένην Λεύκην</span>; 826e 22; 1063, 5; PPetr II, 45 II, 20; BGU 1000, 6; PCairGoodsp 9, 4; O. Wilck II, 1210, 4). O nome: <span class=\"greek\">ἀδελφὴ καλουμένη Μαριάμ</span> uma irmã chamada Maria <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.39\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 10:39</a> (PCairMasp 23, 16 <span class=\"greek\">τ</span>. <span class=\"greek\">ἀδελφὴν καλουμένην Πρόκλαν</span>; TestJob 48:1 <span class=\"greek\">ἡ καλουμένη Ἡμέρα</span>). Cf. 19:2; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.58\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:58</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.19.11\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 19:11</a>, também 12:9. <span class=\"greek\">πόλις καλουμένη Ν</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.11\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:11</a>; cf. 9:10; 19:29; 21:37; 23:33; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 1:12</a>; 3:11; 8:10; 9:11; 10:1; 27:8, 14, 16; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.1.9\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 1:9</a>; 16:16; GPt 6:24. O sobrenome (2 Macc 10:12 <span class=\"greek\">Πτολεμαῖος ὁ καλούμενος Μάκρων</span>; 1 Macc 3:1; Jos., Ant. 13, 367; TestJob 1:1 <span class=\"greek\">Ιωβ τοῦ καλουμένου Ιωβαβ</span>): <span class=\"greek\">Σίμων ὁ κ</span>. <span class=\"greek\">ζηλωτής</span> Simão, o Zelote <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.15\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:15</a>. Cf. 1:36; 8:2; 22:3 (veja <span class=\"greek\">ἐπικαλέω</span> 2); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.23\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 1:23</a>; 13:1; 15:22 (veja <span class=\"greek\">ἐπικαλέω</span>), 37.—O exemplo do Antigo Testamento (Gen 17:19; 1 Km 1:20; Hos 1:9; 1 Macc 6:17) influenciou a expressão <span class=\"greek\">καλεῖν τὸ ὄνομά τινος</span>, com o nome acrescentado em acusativo <span class=\"greek\">καλέσεις τὸ ὄνομα αὐτοῦ Ἰησοῦν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.1.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 1:21</a>; GJs 11:3; 14:2. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.1.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 1:23</a> (Is 7:14), 25; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.13\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:13</a>, 31. Na voz passiva: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.21\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:21</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.19.13\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 19:13</a>.\n ⓓ Muito frequentemente, a ênfase recai menos sobre quais são os nomes e mais sobre o fato de que os portadores desses nomes realmente são aquilo que os nomes afirmam acerca deles. O passivo «ser chamado» aproxima-se, assim, do sentido de «ser»; cabe à sensibilidade do intérprete decidir se essa tradução é adequada em cada caso (Quint. Smyrn. 14, 434 <span class=\"greek\">οὔτ</span>’ <span class=\"greek\">ἔτι σεῖο κεκλήσομαι</span>=não quero mais ser tua, isto é, tua filha). Entre tais construções passivas encontram-se: <span class=\"greek\">Ναζωραῖος κληθήσεται</span> ele será nazareno <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.2.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 2:23</a>. <span class=\"greek\">υἱοὶ θεοῦ κληθήσονται</span> 5:9; cf. versículo 19ab. <span class=\"greek\">υἱὸς ὑψίστου κληθήσεται</span> (em paralelismo com <span class=\"greek\">ἔσται μέγας</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.32\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:32</a>; assim em GJs 11:3, mas sem referência à grandeza; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.35\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:35</a>, 76; 2:23. <span class=\"greek\">οὐκέτι εἰμὶ ἄξιος κληθῆναι υἱός σου</span> 15:19, 21. <span class=\"greek\">οὐκ εἰμὶ ἱκανὸς καλεῖσθαι ἀπόστολος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.9\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 15:9</a>. <span class=\"greek\">ἵνα τέκνα θεοῦ κληθῶμεν</span>, <span class=\"greek\">καί ἐσμέν</span> para que sejamos chamados filhos de Deus; e realmente o somos 1J 3:1 (semelhantemente em Eur., Ion 309 <span class=\"greek\">τ</span>. <span class=\"greek\">θεοῦ καλοῦμαι δοῦλος εἰμί τε</span>; cf. Just., D. 123, 9; <span class=\"greek\">καλεῖσθαι</span> ao lado de <span class=\"greek\">εἶναι</span> como em Plut., Demetr. 900 [25, 6]). <span class=\"greek\">οἱ κεκλημένοι ἐν ὀνόματι κυρίου</span> aqueles que são identificados pelo nome do Senhor, isto é, como cristãos Hs 8, 1, 1. <span class=\"greek\">ἄχρις οὗ τὸ σήμερον καλεῖται</span> enquanto se chama «hoje», enquanto dura o «hoje» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.3.13\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 3:13</a> (WLorimer, NTS 12, ’66, 390f, citando Pla., Phd. 107c).—Também se pode incluir aqui <span class=\"greek\">ἐν Ἰσαὰκ κληθήσεταί σοι σπέρμα</span> em (por meio de) Isaque terás descendência <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.9.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 9:7</a> e <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.18\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:18</a> (Gen 21:12).\n ② solicitar a presença de alguém numa reunião social, convidar (Hom. e outros; pap; 2 Km 13:23; Esth 5:12; ISardRobert 1, ’64, p. 9, linhas 1–4) <span class=\"greek\">τινά</span>, alguém <span class=\"greek\">εἰς</span> (<span class=\"greek\">τοὺς</span>) <span class=\"greek\">γάμους</span>, para as bodas (Diod S 4, 70, 3; POxy 1487, 1 <span class=\"greek\">καλεῖ σε Θέων εἰς τοὺς γάμους</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.22.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 22:9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.14.8\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 14:8</a>, cf. versículo 10 (Sinônimo: <span class=\"greek\">ἐρωτάω</span>; veja três textos de convites à <span class=\"greek\">κλινή</span> de Serápis [ZPE 1, ’67, 121–26], dois com <span class=\"greek\">ἐ</span>. e um com <span class=\"greek\">καλέω</span>, New Docs 1, 5–9; quanto ao uso literário do contexto das refeições por Lucas, veja XdeMeeûs, ETL 37, ’61, 847–70; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.2.2\" target=\"_blank\" rel=\"noopener noreferrer\">J 2:2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.19.9\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 19:9</a>. Em uso absoluto: convidar <span class=\"greek\">τινά</span>, alguém <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.10.27\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 10:27</a> (Diog. L. 7, 184, a respeito de Crisipo: <span class=\"greek\">ἐπὶ θυσίαν</span> [refeição sacrificial] <span class=\"greek\">ὑπὸ τῶν μαθητῶν κληθῆναι</span>); sacerdotes para o aniversário de uma criança GJs 6:2. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.39\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:39</a>; 14:9, 12f, 16. <span class=\"greek\">οἱ κεκλημένοι</span> os convidados (Damox. Com. [IV/III b.c.] Fgm. 2, 26 K. in Athen. 3, 59, 102c <span class=\"greek\">τ</span>. <span class=\"greek\">κεκλημένον</span>; Jos., Ant. 6, 48; 52); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.22.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 22:3b</a> (<span class=\"greek\">οἱ κεκλημένοι εἰς τ</span>. <span class=\"greek\">γάμους</span> como Diphilus Com. [IV/III b.c.] Fgm. 17, 1), 4, 8; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.14.7\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 14:7</a>, 17; cf. versículo 24. <span class=\"greek\">ὁ κεκληκώς</span>, o anfitrião 14:10 (veja acima).—Se <span class=\"greek\">αὐτοῦ</span> em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 2:15</a> se refere à casa de Jesus, <span class=\"greek\">κ</span>. no versículo 17 apresenta o duplo sentido de convite para uma refeição e de recebimento dos benefícios messiânicos, tendo Jesus como anfitrião (veja AMcNeile, Mt ’57, 118); diferentemente em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.27\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:27</a>–32; veja a acepção 4 abaixo. De um novo chamado aos convidados, depois de concluídos os preparativos do banquete <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.22.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 22:3a</a> (cf. 3b abaixo).\n ③ usar autoridade para fazer comparecer uma pessoa ou grupo, convocar\n ⓐ reunir por convocação pessoas (<span class=\"greek\">τινάς</span>): trabalhadores para receber pagamento <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.20.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 20:8</a>. escravos para receber ordens 25:14; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.19.13\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 19:13</a>. pastores GJs 4:3. <span class=\"greek\">τὰς θυγατέρας τῶν Ἑβραίων</span> para entreter Maria 6:1; 7:2. <span class=\"greek\">τὰς παρθένους</span> Ox 404 recto, 21 (Hs 113, 5); GJs 10:1. convidados <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.22.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 22:3a</a> (veja o fim da acepção 2).\n ⓑ convocar alguém (<span class=\"greek\">τινά</span>) (Appian, Bell. Civ. 4, 82 §347; 4, 86 §362; 1 Macc 1:6) <span class=\"greek\">ἀπέστειλαν πρὸς αὐτὸν καλοῦντες αὐτόν</span> enviaram mensageiros a ele para convocá-lo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.31\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 3:31</a>. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.2.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 2:7</a>; 22:3a. Referindo-se a José <span class=\"greek\">ἐκάλεσεν αὐτήν</span> GJs 13:2 (quanto ao contexto, cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.1.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 1:18f</a>). Referindo-se a Deus: os israelitas chamados do Egito (como tipo de Cristo) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.2.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 2:15</a>.—Chamar para comparecer (Himerius, Or. 48 [=Or. 14], 10; 4 Macc 3:19) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.8\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:8</a>.\n ⓒ termo técnico jurídico: citar, convocar para comparecer perante um tribunal (frequente em papiros) <span class=\"greek\">τινά</span>, alguém (Jos., Ant. 14, 169) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.18\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 4:18</a>; 24:2.—A transição para a acepção 4 é bem exemplificada por <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.4.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 4:21</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:20</a>; Papias (8), em que a convocação também constitui chamado ao discipulado.\n ④ Dos sentidos «convocar» e «convidar» desenvolve-se a acepção ampliada de «escolher alguém para receber um benefício ou uma experiência especial», chamar (Paus. 10, 32, 13 <span class=\"greek\">οὓς ἂν ἡ ῏Ισις καλέσῃ δι</span>’ <span class=\"greek\">ἐνυπνίων</span>; Ael. Aristid. 30, 9 K.=10 p. 116 D.: <span class=\"greek\">ὑπὸ τοῦ θεοῦ κληθείς</span>) <span class=\"greek\">καλούμενος ὑπὸ τοῦ θεοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.5.4\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 5:4</a>. <span class=\"greek\">τινὰ εἴς τι</span> alguém para algo, no uso do Novo Testamento e da LXX, designando a escolha de pessoas para a salvação: Deus (muito mais raramente Cristo) chama <span class=\"greek\">εἰς τὴν ἑαυτοῦ βασιλείαν καὶ δόξαν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.2.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 2:12</a>; <span class=\"greek\">εἰς τὴν αἰώνιον αὐτοῦ δόξαν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.5.10\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 5:10</a>. <span class=\"greek\">εἰς ζωὴν αἰώνιον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.6.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 6:12</a>. <span class=\"greek\">εἰς κοινωνίαν τοῦ υἱοῦ αὐτοῦ</span> para a comunhão com seu Filho <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.1.9\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 1:9</a>. <span class=\"greek\">ἐκ σκότους εἰς τὸ αὐτοῦ φῶς</span> das trevas para sua luz <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.9\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 2:9</a>. <span class=\"greek\">ἀπὸ σκότους εἰς φῶς</span> 1 Cl 59:2. <span class=\"greek\">διὰ τ</span>. <span class=\"greek\">χάριτος αὐτοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.1.15\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 1:15</a>. para isso Deus vos chamou por meio de nossa proclamação, a saber, para alcançar a glória <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.2.14\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 2:14</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.2.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 2:12</a>. <span class=\"greek\">καλέσαντι</span> … <span class=\"greek\">εἰς τὴν μερίδα τοῦ κλήρους τῶν ἁγίων</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.1.12\" target=\"_blank\" rel=\"noopener noreferrer\">Col 1:12</a> variante textual (em lugar de <span class=\"greek\">ἱκανώσαντι</span>). Sem complementação adicional <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.30\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 8:30</a>; 9:24; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.17\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 7:17f</a>, 20–22, 24; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.1.11\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 1:11</a> variante textual; 2 Cl 9:5; 10:1.—<span class=\"greek\">κ</span>. <span class=\"greek\">κλήσει ἁγίᾳ</span> chamar com santa vocação <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.1.9\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 1:9</a>. <span class=\"greek\">ἀξίως τῆς κλήσεως ἧς</span> (atração do relativo, em lugar de <span class=\"greek\">ἣν</span>) <span class=\"greek\">ἐκλήθητε</span> de maneira digna da vocação com que fostes chamados <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.1\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 4:1</a> (quanto à construção, veja W-S. §24, 4b; Rob. 478). Referindo-se a Deus: <span class=\"greek\">ὁ καλῶν τινά</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.5.8\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 5:8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.5.24\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 5:24</a>. Em uso absoluto, <span class=\"greek\">ὁ καλῶν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.9.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 9:12</a>. <span class=\"greek\">ὁ καλέσας τινά</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.1.6\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 1:6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.15\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 1:15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 1:3</a>. Da mesma forma, referindo-se a Cristo <span class=\"greek\">ὁ καλέσας τινά</span> 2 Cl 5:1 (Just., A I, 15, 7). Na voz passiva: <span class=\"greek\">οἱ κεκλημένοι</span> os chamados <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.9.15\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 9:15</a>. <span class=\"greek\">κεκλημένοι ὑπὸ τοῦ θεοῦ δι</span>’ <span class=\"greek\">αὐτοῦ</span> (=<span class=\"greek\">Ἰ</span>. <span class=\"greek\">Χρ</span>.) 1 Cl 65:2. <span class=\"greek\">οἱ κεκλημένοι ὑπ</span>’ <span class=\"greek\">αὐτοῦ</span> (=<span class=\"greek\">υἱοῦ τ</span>. <span class=\"greek\">θεοῦ</span>) Hs 9, 14, 5. <span class=\"greek\">οἱ κληθέντες</span> Hm 4, 3, 4. Veja também 1d.—Com especificações mais precisas: <span class=\"greek\">ἐν δικαιοσύνῃ</span> B 14:7 (Is 42:6). <span class=\"greek\">ἐπ</span>’ <span class=\"greek\">ἐλευθερίᾳ</span> (veja <span class=\"greek\">ἐλευθερία</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.5.13\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 5:13</a>. <span class=\"greek\">οὐκ ἐπὶ ἀκαθαρσίᾳ ἀλλ</span>’ <span class=\"greek\">ἐν ἁγιασμῷ</span> não para impureza, mas para santificação <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.4.7\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 4:7</a>. <span class=\"greek\">ἐν εἰρήνῃ</span> em paz <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.15\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 7:15</a>. <span class=\"greek\">ἐκλήθητε ἐν μιᾷ ἐλπίδι τῆς κλήσεως ὑμῶν</span> fostes chamados na única esperança que partilhais em vossa vocação <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.4\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 4:4</a>. <span class=\"greek\">ἡμεῖς διὰ θελήματος αὐτου</span> (=<span class=\"greek\">θεοῦ</span>) <span class=\"greek\">ἐν Χριστῷ Ἰησοῦ κληθέντες</span> 1 Cl 32:4. <span class=\"greek\">εἰς εἰρήνην τοῦ Χριστοῦ ἐν ἐνὶ σώματι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.3.15\" target=\"_blank\" rel=\"noopener noreferrer\">Col 3:15</a>. <span class=\"greek\">ἐν τῇ σαρκί</span> 2 Cl 9:4. <span class=\"greek\">ἐν Ἰσαάκ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.18\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:18</a> (=<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.9.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 9:7</a>). <span class=\"greek\">πόθεν ἐκλήθημεν καὶ ὑπὸ τίνος καὶ εἰς ὸ̔ν τόπον</span> 2 Cl 1:2. <span class=\"greek\">εἰς τοῦτο ἵνα</span> para isso, a fim de que <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.3.9\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 3:9</a>; cf. 2:21. Referindo-se a Cristo: <span class=\"greek\">οὐκ ἦλθον καλέσαι δικαίους ἀλλὰ ἁμαρτωλούς</span> (+ <span class=\"greek\">εἰς μετάνοιαν</span> variante textual) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.9.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 9:13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 2:17</a> (quanto ao provável duplo sentido desta passagem, veja a acepção 2); 2 Cl 2:4; cf. versículo 7 (cf. Just., A I, 40, 7 <span class=\"greek\">εἰς μετάνοιαν καλεῖ πάντας ὁ θεός</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.32\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:32</a> (<span class=\"greek\">ἐλήλυθα</span> … <span class=\"greek\">εἰς μετάνοιαν</span>). Referindo-se a Deus: <span class=\"greek\">ἐκάλεσεν ἡμᾶς οὐκ ὄντας</span> ele nos chamou quando ainda não existíamos 2 Cl 1:8. <span class=\"greek\">ὁ καλῶν τὰ μὴ ὄντα ὡς ὄντα</span> aquele que chama à existência as coisas que não existem <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.4.17\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 4:17</a> (Philo, Spec. Leg. 4, 187 <span class=\"greek\">τὰ μὴ ὄντα ἐκάλεσεν εἰς τὸ εἶναι</span>; cf. Is 41:4; 48:13).—Sobre o chamado de Deus para um ofício <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.5.4\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 5:4</a>.—JHempel, Berufung u. Bekehrung (também em GBeer Festschr.) ’35; HWildberger, Jahwes Eigentumsvolk ’60.—B. 1276. DELG. EDNT. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0184-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καλιά, ᾶς, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(Hesíodo e outros [«morada de madeira, cabana»]; desde Teócrito «ninho de pássaro», também Gen 6:14 [Símaco em lugar de <span class=\"greek\">νοσσίας</span>]; PSI 569, 2 «gaiola») ninho de pássaro <span class=\"greek\">ἐν τῇ δαφνιδέᾳ</span> Ana viu um ninho de pardais no loureiro GJs 3:1.—DELG.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0184-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καλλιέλαιος, ου, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(veja <span class=\"greek\">καλός</span>, <span class=\"greek\">ἐλαία</span>) a oliveira cultivada (em oposição a <span class=\"greek\">ἀγριέλαιος</span>, oliveira silvestre; esta contraposição já ocorre em Aristóteles, De Plant. 1, 6, 820b, 40) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.11.24\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 11:24</a>.—OPlasberg, APF 2, 1903, 219ff; aqui, de um papiro de Estrasburgo, as palavras <span class=\"greek\">εἰς καλλιελαίαν</span>. A palavra, como adjetivo, também em PEdg 21, 3=Sb 6727, 3 (257/256 b.c.). Cf. Nicetas Coniates, De Manuele Comneno 4, 4 (MPG CXXXIX 480) a respeito de um genro húngaro na corte bizantina: <span class=\"greek\">μήτε τὸν ἐκ φυταλιᾶς ἑτεροφύλου ῥάδαμνον εἰς καλλιέλαιον μετεγκεντρίζειν πιότατον</span> «nem tomar um rebento de um pomar estranho e enxertá-lo numa oliveira muito produtiva». Uma expressão muito semelhante a esta aparece em Psellus p. 99, 17.—Bibliografia sob <span class=\"greek\">ἀγριέλαιος</span> e <span class=\"greek\">ἐλαία</span> 2.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0184-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κάλλιον</h1><div class=\"entry-meta\"><span>remissão lexical</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">veja <span class=\"greek\">καλῶς</span> 7.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0184-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καλλονή, ῆς, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(Eur., Hdt.+; SIG 783, 46; 51; PFlor 65, 12; PLond V, 1764, 4; LXX; En 24:2; PsSol 12:2 [<span class=\"greek\">καλάμην</span>, leitura H]; JosAs 18 cod. A [p. 68, 18 Bat.] e Pal. 364; EpArist) beleza, com referência à glória futura 1 Cl 35:3. <span class=\"greek\">τὸ μεγαλεῖον τῆς κ</span>. <span class=\"greek\">τοῦ θεοῦ</span> grande beleza 49:3.—DELG sob o verbete <span class=\"greek\">καλό</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0184-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κάλλος, ους, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(Hom.+; LXX; pseudoepígrafos; Philo; Jos., C. Ap. 1, 195; 2, 167; Just., A II, 11, 5; Tat. 2, 2; Ath.) beleza 1 Cl 16:3 (Is 53:2); Hv 1, 1, 2; 3, 10, 5; Hs 9, 13, 9; AcPl Ha 2, 21; 25, 9; 9, 10. <span class=\"greek\">κ</span>. <span class=\"greek\">τῆς ὄψεως</span> do rosto ApcPt 3:7.—DELG sob o verbete <span class=\"greek\">καλός</span> 2. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0184-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καλλωπίζω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(veja <span class=\"greek\">καλός</span>, <span class=\"greek\">ὤψ</span>, «rosto»; X., Pla.; LXX, TestAbr; JosAs cod. A [p. 43, 7 e 15 Bat.]; ApcSed 11:7 e 17 [p. 134, 19 e 37 Ja.]; Jos., Ant. 1, 121; Just., D. 29, 2 <span class=\"greek\">λόγοι</span> … <span class=\"greek\">τέχνῃ ἀνθρωπίνῃ κεκαλλωπισμένοι</span>) imperativo aoristo <span class=\"greek\">καλλώπισον</span> (TestAbr A 4 p. 80, 20 [Stone p. 8]); aoristo, 3ª pessoa do singular, voz média <span class=\"greek\">ἐκαλλιωπίσατο</span> LXX; particípio perfeito passivo <span class=\"greek\">κεκαλλωπισμένος</span> (LXX, Just.) «embelezar o rosto» (Galen, Protr. 10 p. 34, 2 J.=p. 15, 3 Kaibel=p. 121, 15 M.), também em sentido geral, adornar, embelezar (Philostrat., Ep. 27 p. 239, 28 <span class=\"greek\">ἵππους</span>; Theoph. Ant. 2, 12 [p. 130, 13]) Ox 840, 38.—DELG e Frisk sob o verbete <span class=\"greek\">ὄπωπα</span>, também Frisk sob o verbete *<span class=\"greek\">ωψ</span>.</p></section></article>\n"};
